// Fetch recent Federal Register documents for each agency and map them to
// the upsert_finding() argument shape. Mirrors scraper/sources.py
// FederalRegisterSource exactly (category lookup, priority arithmetic, verbatim
// abstract, verified provenance). One agency failing must not sink the rest.

const LOOKBACK_DAYS = 14;
const today = new Date();
const reportDate = today.toISOString().slice(0, 10);
const since = new Date(today.getTime() - LOOKBACK_DAYS * 86400000).toISOString().slice(0, 10);

const AGENCIES = [
  { authority: 'FAA',   slug: 'federal-aviation-administration' },
  { authority: 'FDA',   slug: 'food-and-drug-administration' },
  { authority: 'NHTSA', slug: 'national-highway-traffic-safety-administration' },
];

const FR_CATEGORY = {
  'Rule': 'final_rule',
  'Proposed Rule': 'nprm',
  'Notice': 'notice',
  'Presidential Document': 'presidential_document',
};
const FIELDS = ['document_number','title','type','abstract','publication_date','effective_on','comments_close_on','html_url','docket_ids'];

function daysUntil(d) {
  if (!d) return null;
  const t = Date.parse(d + 'T00:00:00Z');
  if (Number.isNaN(t)) return null;
  const start = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate());
  return Math.round((t - start) / 86400000);
}
function derivePriority(eff, deadline) {
  const dd = daysUntil(deadline); const ed = daysUntil(eff);
  const d = (dd !== null && dd >= 0) ? dd : null;
  const e = (ed !== null && ed >= 0) ? ed : null;
  if ((d !== null && d <= 7)  || (e !== null && e <= 7))  return 'urgent';
  if ((d !== null && d <= 30) || (e !== null && e <= 30)) return 'high';
  if (d !== null || e !== null) return 'normal';
  return 'low';
}

const out = [];
for (const a of AGENCIES) {
  const qs = new URLSearchParams();
  qs.set('per_page', '200');
  qs.set('order', 'newest');
  qs.append('conditions[agencies][]', a.slug);
  qs.append('conditions[publication_date][gte]', since);
  for (const f of FIELDS) qs.append('fields[]', f);
  const url = 'https://www.federalregister.gov/api/v1/documents.json?' + qs.toString();

  let resp;
  try {
    resp = await this.helpers.httpRequest({
      method: 'GET', url, json: true,
      headers: { 'User-Agent': 'Conform-Edge RegIntel/1.0 (+https://conform-edge.com; n8n)' },
    });
  } catch (e) {
    // Surface the gap by logging; do not fail the whole run.
    console.log('Federal Register fetch failed for ' + a.authority + ': ' + e.message);
    continue;
  }

  for (const doc of (resp.results || [])) {
    const link = doc.html_url;
    const title = (doc.title || '').trim();
    if (!link || !title) continue;

    const dockets = doc.docket_ids || [];
    const detail = [
      doc.document_number ? ('Document ' + doc.document_number) : null,
      doc.type || null,
      dockets.length ? ('Docket ' + dockets.join(', ')) : null,
      doc.publication_date ? ('Published ' + doc.publication_date) : null,
    ].filter(Boolean).join(' \u00b7 ');
    const abstract = (doc.abstract || '').trim();
    const summary = abstract || ((doc.type || 'Document') + ' published ' + (doc.publication_date || 'date not stated') + '.');

    out.push({ json: {
      p_finding_key: (doc.document_number || '').trim() || link,
      p_authority: a.authority,
      p_category: FR_CATEGORY[doc.type] || 'other',
      p_priority: derivePriority(doc.effective_on, doc.comments_close_on),
      p_title: title,
      p_summary: summary,
      p_detail: detail,
      p_source_url: link,
      p_effective_date: doc.effective_on || null,
      p_comment_deadline: doc.comments_close_on || null,
      p_document_number: doc.document_number || null,
      p_verification: 'verified',
      p_source_id: 'federal-register',
      p_report_date: reportDate,
    } });
  }
}
return out;
